  "Employee status": "ملازم کی حالت",
  "Keep current": "موجودہ برقرار رکھیں",
  "Applied immediately — no pending-approval queue exists for this action yet.": "فوراً نافذ ہوتا ہے — اس کارروائی کے لیے ابھی منظوری کی کوئی قطار موجود نہیں۔",
  "APPROVAL & REVERSIBILITY": "منظوری اور واپسی کی گنجائش",
  "Approval route": "منظوری کا راستہ",
  "BEFORE → AFTER": "پہلے ← بعد",
  "EMPLOYEE DETAILS — NOT CHANGED BY THIS ACTION": "ملازم کی تفصیلات — اس کارروائی سے تبدیل نہیں ہوتیں",
  "I have verified these values and I am authorised to apply this separation.": "میں نے ان قدروں کی تصدیق کر لی ہے اور مجھے یہ علیحدگی نافذ کرنے کا اختیار ہے۔",
  "Pending approval — a real multi-stage approval chain runs on this request.": "منظوری زیر التوا — اس درخواست پر کئی مراحل پر مشتمل حقیقی منظوری کا سلسلہ چلتا ہے۔",
  "Pending approval — nothing changes until every approver on the route has approved.": "منظوری زیر التوا — راستے کے ہر منظور کنندہ کی منظوری تک کچھ نہیں بدلتا۔",
  "Raised by": "درخواست دہندہ",
  "Recording a separation ends the current record and starts the exit process. It cannot be reversed — a returning employee needs a fresh Hire action.": "علیحدگی درج کرنے سے موجودہ ریکارڈ ختم ہو جاتا ہے اور رخصتی کا عمل شروع ہوتا ہے۔ اسے واپس نہیں کیا جا سکتا — واپس آنے والے ملازم کے لیے نئی بھرتی کی کارروائی درکار ہے۔",
  "Reversibility": "واپسی کی گنجائش",
  "Status on apply": "نفاذ پر حالت",
  "This cannot be undone": "یہ عمل واپس نہیں ہو سکتا",
  "unchanged": "بغیر تبدیلی",
  "HR Business Partner → Payroll Admin.": "ایچ آر بزنس پارٹنر ← پے رول ایڈمن۔",
  "HR, then Branch Admin (this employee is a manager, per the real separation approval chain).": "ایچ آر، پھر برانچ ایڈمن (یہ ملازم مینیجر ہے، علیحدگی کی حقیقی منظوری کے سلسلے کے مطابق)۔",
  "Not reversible. Undoing a separation requires a fresh Hire action and a new employee record — the original number is not reissued.": "واپس نہیں ہو سکتا۔ علیحدگی ختم کرنے کے لیے نئی بھرتی کی کارروائی اور نیا ملازم ریکارڈ درکار ہے — اصل نمبر دوبارہ جاری نہیں ہوتا۔",
  "Reporting manager (raises) → HR Business Partner, then Payroll Admin if a new CTC is included.": "رپورٹنگ مینیجر (درخواست دیتا ہے) ← ایچ آر بزنس پارٹنر، پھر نیا CTC شامل ہو تو پے رول ایڈمن۔",
  "Reporting manager (raises) → HR Business Partner.": "رپورٹنگ مینیجر (درخواست دیتا ہے) ← ایچ آر بزنس پارٹنر۔",
  "Reporting manager, then HR (the real separation approval chain for this employee).": "رپورٹنگ مینیجر، پھر ایچ آر (اس ملازم کے لیے علیحدگی کی حقیقی منظوری کا سلسلہ)۔",
  "Requires employees.confirm — HR/Admin applies this directly, with the effective date and reason recorded in the audit trail.": "employees.confirm درکار ہے — ایچ آر/ایڈمن اسے براہ راست نافذ کرتا ہے، اور نفاذ کی تاریخ اور وجہ آڈٹ ٹریل میں درج ہوتی ہے۔",
  "Requires employees.edit — applied directly by whoever has that permission (typically the reporting manager or HR); no queued approval step exists for this action yet.": "employees.edit درکار ہے — یہ اجازت رکھنے والا (عموماً رپورٹنگ مینیجر یا ایچ آر) براہ راست نافذ کرتا ہے؛ اس کارروائی کے لیے ابھی منظوری کا کوئی قطار شدہ مرحلہ نہیں۔",
  "Requires employees.edit — currently held by {name} or HR; no queued approval step exists for this action yet.": "employees.edit درکار ہے — فی الحال {name} یا ایچ آر کے پاس ہے؛ اس کارروائی کے لیے ابھی منظوری کا کوئی قطار شدہ مرحلہ نہیں۔",
  "Requires employees.edit; no queued approval step exists for this action yet.": "employees.edit درکار ہے؛ اس کارروائی کے لیے ابھی منظوری کا کوئی قطار شدہ مرحلہ نہیں۔",
  "Requires payroll.edit — typically an HR Business Partner or Payroll Admin; no queued approval step exists for this action yet.": "payroll.edit درکار ہے — عموماً ایچ آر بزنس پارٹنر یا پے رول ایڈمن؛ اس کارروائی کے لیے ابھی منظوری کا کوئی قطار شدہ مرحلہ نہیں۔",
  "Reversible going forward, but any payroll run already processed on this record must be corrected through arrears.": "آئندہ کے لیے واپس ہو سکتا ہے، لیکن اس ریکارڈ پر پہلے سے پروسیس شدہ کوئی بھی پے رول بقایا جات کے ذریعے درست کرنا ہوگا۔",
  "Reversible. A correction action delimits this record and restores the previous position; the history keeps both.": "واپس ہو سکتا ہے۔ درستی کی کارروائی اس ریکارڈ کی حد مقرر کر کے پچھلا عہدہ بحال کرتی ہے؛ تاریخ میں دونوں محفوظ رہتے ہیں۔",
  "Reversible. Record a further org assignment to move the employee back.": "واپس ہو سکتا ہے۔ ملازم کو واپس منتقل کرنے کے لیے ایک اور ادارہ جاتی تفویض درج کریں۔",
