  "This marks all {count} payslip (total {amount}) as paid and closes this payroll run. This does not itself transfer money — it records that the transfer already happened. This cannot be undone.": "یہ تمام {count} تنخواہ پرچی (کل {amount}) کو ادا شدہ نشان زد کرتا ہے اور اس پے رول رن کو بند کر دیتا ہے۔ اس سے خود رقم منتقل نہیں ہوتی — یہ صرف درج کرتا ہے کہ منتقلی پہلے ہو چکی ہے۔ اسے واپس نہیں کیا جا سکتا۔",
  "This marks all {count} payslips (total {amount}) as paid and closes this payroll run. This does not itself transfer money — it records that the transfer already happened. This cannot be undone.": "یہ تمام {count} تنخواہ کی پرچیوں (کل {amount}) کو ادا شدہ نشان زد کرتا ہے اور اس پے رول رن کو بند کر دیتا ہے۔ اس سے خود رقم منتقل نہیں ہوتی — یہ صرف درج کرتا ہے کہ منتقلی پہلے ہو چکی ہے۔ اسے واپس نہیں کیا جا سکتا۔",
