  "A {entity} files a CIN and needs directors with DINs. PAN 4th char should be C.": "{entity} کا CIN ہوتا ہے اور اسے DIN والے ڈائریکٹرز درکار ہیں۔ PAN کا چوتھا حرف C ہونا چاہیے۔",
  "A foreign {entity} is identified by its local incorporation number and tax ID. India-specific IDs (PAN, GSTIN, TAN) don't apply.": "غیر ملکی {entity} کی شناخت اس کے مقامی قیام نمبر اور ٹیکس آئی ڈی سے ہوتی ہے۔ بھارت کے مخصوص شناختی نمبر (PAN، GSTIN، TAN) لاگو نہیں ہوتے۔",
  "A Partnership Firm doesn't file a CIN — enter its registration number from the certificate instead. PAN 4th char should be F.": "پارٹنرشپ فرم کا CIN نہیں ہوتا — اس کے بجائے سرٹیفکیٹ سے اس کا رجسٹریشن نمبر درج کریں۔ PAN کا چوتھا حرف F ہونا چاہیے۔",
  "A Proprietorship uses the proprietor's own PAN (4th char P) — no separate CIN or firm PAN.": "سنگل ملکیت میں مالک کا اپنا PAN استعمال ہوتا ہے (چوتھا حرف P) — الگ CIN یا فرم کا PAN نہیں ہوتا۔",
  "A Trust or Society is registered under trust/society law, not the Companies Act — no CIN. Identified by its own PAN (4th char T for a Trust, A for a Society) and registration certificate.": "ٹرسٹ یا سوسائٹی ٹرسٹ/سوسائٹی کے قانون کے تحت رجسٹرڈ ہوتی ہے، کمپنیز ایکٹ کے تحت نہیں — کوئی CIN نہیں۔ اس کی شناخت اس کے اپنے PAN (ٹرسٹ کے لیے چوتھا حرف T، سوسائٹی کے لیے A) اور رجسٹریشن سرٹیفکیٹ سے ہوتی ہے۔",
  "An HUF isn't registered under the Companies Act — no CIN. It's identified by its own HUF PAN (4th char H) and the karta's details.": "HUF کمپنیز ایکٹ کے تحت رجسٹرڈ نہیں ہوتا — کوئی CIN نہیں۔ اس کی شناخت اس کے اپنے HUF PAN (چوتھا حرف H) اور کرتا کی تفصیلات سے ہوتی ہے۔",
  "An LLP doesn't file a CIN — it's identified by its LLPIN, filed under the LLP Act rather than the Companies Act. PAN 4th char should be F.": "LLP کا CIN نہیں ہوتا — اس کی شناخت اس کے LLPIN سے ہوتی ہے، جو کمپنیز ایکٹ کے بجائے LLP ایکٹ کے تحت درج ہوتا ہے۔ PAN کا چوتھا حرف F ہونا چاہیے۔",
  "Belongs to PAN {pan}, not the company PAN.": "یہ PAN {pan} کا ہے، کمپنی کے PAN کا نہیں۔",
  "City is required.": "شہر ضروری ہے۔",
