  "Face registration needs your camera. Allow camera access for this site in your browser's settings, then try again.": "چہرے کی رجسٹریشن کے لیے آپ کا کیمرا درکار ہے۔ اپنے براؤزر کی ترتیبات میں اس سائٹ کے لیے کیمرا کی رسائی دیں، پھر دوبارہ کوشش کریں۔",
