  "Registration needs both a natural blink and a slight head turn, and we didn't see both in time. Make sure you're well-lit and centered, then try again.": "رجسٹریشن کے لیے قدرتی پلک جھپکنا اور سر کا ہلکا سا موڑنا دونوں ضروری ہیں، اور ہم نے دونوں وقت پر نہیں دیکھے۔ یقینی بنائیں کہ روشنی اچھی ہے اور آپ بیچ میں ہیں، پھر دوبارہ کوشش کریں۔",
