  "We'll ask for camera access, run a quick liveness check (a blink and a slight head turn) to confirm it's really you, then send your face ID for HR approval. No photo or video is ever sent — only a numeric face signature.": "ہم کیمرا کی رسائی مانگیں گے، آپ کی تصدیق کے لیے ایک فوری لائیونیس جانچ (پلک جھپکنا اور سر کا ہلکا موڑ) کریں گے، پھر آپ کا Face ID ایچ آر کی منظوری کے لیے بھیجیں گے۔ کوئی تصویر یا ویڈیو نہیں بھیجی جاتی — صرف چہرے کا عددی دستخط۔",
  "We'll ask for camera access, run a quick liveness check (a blink and a slight head turn) to confirm it's really you, then send your updated face ID for HR approval. No photo or video is ever sent — only a numeric face signature.": "ہم کیمرا کی رسائی مانگیں گے، آپ کی تصدیق کے لیے ایک فوری لائیونیس جانچ (پلک جھپکنا اور سر کا ہلکا موڑ) کریں گے، پھر آپ کا اپ ڈیٹ شدہ Face ID ایچ آر کی منظوری کے لیے بھیجیں گے۔ کوئی تصویر یا ویڈیو نہیں بھیجی جاتی — صرف چہرے کا عددی دستخط۔",
