  "Low light detected — your screen is now acting as a light. Raising your screen brightness helps.": "کم روشنی کا پتہ چلا — آپ کی اسکرین اب روشنی کا کام کر رہی ہے۔ اسکرین کی چمک بڑھانے سے مدد ملتی ہے۔",
