  "Turn this on to allow punching in only near the office. Leave it off to allow punching in from anywhere.": "صرف دفتر کے قریب پنچ ان کی اجازت دینے کے لیے اسے آن کریں۔ کہیں سے بھی پنچ ان کی اجازت کے لیے اسے آف رکھیں۔",
