  "Whether it is in use, and whether it is a special office.": "آیا یہ استعمال میں ہے، اور آیا یہ کوئی خاص دفتر ہے۔",
  "With manager": "مینیجر کے پاس",
  "Write your self review and see your outcome.": "اپنا خود جائزہ لکھیں اور اپنا نتیجہ دیکھیں۔",
