  "Please register your Face ID first (Profile > Register My Face), then come back to punch in.": "براہ کرم پہلے اپنی Face ID رجسٹر کریں (پروفائل > میرا چہرہ رجسٹر کریں)، پھر پنچ ان کرنے واپس آئیں۔",
