  "Punched in successfully.": "پنچ ان کامیابی سے ہو گیا۔",
  "Punched out successfully.": "پنچ آؤٹ کامیابی سے ہو گیا۔",
  "Too many failed face verification attempts. Please wait {time} before trying again.": "چہرے کی تصدیق کی بہت زیادہ ناکام کوششیں۔ براہ کرم دوبارہ کوشش سے پہلے {time} انتظار کریں۔",
  "Unable to determine your location. Please check your device's location settings and try again.": "آپ کا مقام معلوم نہیں ہو سکا۔ براہ کرم اپنے ڈیوائس کی مقام کی ترتیبات چیک کریں اور دوبارہ کوشش کریں۔",
  "You are outside the allowed location for this branch.": "آپ اس برانچ کے لیے مقررہ مقام سے باہر ہیں۔",
  "Your browser does not support location access.": "آپ کا براؤزر مقام تک رسائی کی سہولت فراہم نہیں کرتا۔",
  "Choose the filled template first.": "پہلے بھرا ہوا ٹیمپلیٹ منتخب کریں۔",
  "Could not cancel the import.": "امپورٹ منسوخ نہیں ہو سکا۔",
  "Could not create the error file.": "خرابی کی فائل نہیں بن سکی۔",
  "Could not download the error report.": "خرابی کی رپورٹ ڈاؤن لوڈ نہیں ہو سکی۔",
  "Could not download the template.": "ٹیمپلیٹ ڈاؤن لوڈ نہیں ہو سکا۔",
  "Could not open that import.": "وہ امپورٹ کھل نہیں سکا۔",
  "Could not retry the failed emails.": "ناکام ای میلز دوبارہ نہیں بھیجی جا سکیں۔",
  "The connection was lost, so the outcome is unknown. Press Confirm again: this import cannot be applied twice.": "کنکشن ٹوٹ گیا، اس لیے نتیجہ معلوم نہیں۔ دوبارہ تصدیق دبائیں: یہ امپورٹ دو بار لاگو نہیں ہو سکتا۔",
  "The file could not be checked. Nothing was imported.": "فائل کی جانچ نہیں ہو سکی۔ کچھ بھی امپورٹ نہیں ہوا۔",
  "The import was rejected. Nothing was created.": "امپورٹ مسترد ہو گیا۔ کچھ بھی نہیں بنایا گیا۔",
  "{percent}% of headcount · {count} on probation": "کل افراد کا {percent}% · {count} آزمائشی مدت پر",
