  "all assigned a reporting manager": "سب کو رپورٹنگ مینیجر سونپا گیا",
  "Are you sure you want to activate {name}?": "کیا آپ واقعی {name} کو فعال کرنا چاہتے ہیں؟",
  "Are you sure you want to deactivate {name}?": "کیا آپ واقعی {name} کو غیر فعال کرنا چاہتے ہیں؟",
