  "Choose Recommend, Undecided or Do not recommend.": "سفارش کریں، غیر یقینی یا سفارش نہ کریں میں سے انتخاب کریں۔",
  "Could not save your feedback.": "آپ کی رائے محفوظ نہیں ہو سکی۔",
  "Write at least {count} characters of comments.": "کم از کم {count} حروف کے تبصرے لکھیں۔",
  "Could not resend the onboarding email.": "آن بورڈنگ ای میل دوبارہ نہیں بھیجی جا سکی۔",
  "Onboarding email resent.": "آن بورڈنگ ای میل دوبارہ بھیج دی گئی۔",
  "Could not activate the cycle.": "دور فعال نہیں ہو سکا۔",
  "Could not close the cycle.": "دور بند نہیں ہو سکا۔",
  "Could not access the camera. Please check it isn't in use by another app.": "کیمرے تک رسائی نہیں ہو سکی۔ براہ کرم چیک کریں کہ کوئی اور ایپ اسے استعمال نہیں کر رہی۔",
  "Could not capture the photo. Please try again.": "تصویر کیپچر نہیں ہو سکی۔ براہ کرم دوبارہ کوشش کریں۔",
  "Could not record this leave.": "یہ چھٹی درج نہیں ہو سکی۔",
  "End date is before the start date.": "اختتامی تاریخ ابتدائی تاریخ سے پہلے ہے۔",
  "Half day applies to a single date only.": "آدھا دن صرف ایک تاریخ پر لاگو ہوتا ہے۔",
  "Leave recorded — {days} day from {date}.": "چھٹی درج ہو گئی — {date} سے {days} دن۔",
  "Leave recorded — {days} days from {date}.": "چھٹی درج ہو گئی — {date} سے {days} دن۔",
  "That range contains only weekly offs.": "اس دورانیے میں صرف ہفتہ وار چھٹیاں ہیں۔",
  "Could not download this report.": "یہ رپورٹ ڈاؤن لوڈ نہیں ہو سکی۔",
  "Could not send this report.": "یہ رپورٹ بھیجی نہیں جا سکی۔",
  "Salary saved.": "تنخواہ محفوظ ہو گئی۔",
  "Failed to save the declaration.": "اعلان محفوظ نہیں ہو سکا۔",
